<?= $this->extend('admin/layouts/main') ?><?= $this->section('content') ?><?php $selling=(new \App\Services\ProductService())->effectivePrice($product);$profit=$product['purchase_cost']!==null?$selling-(float)$product['purchase_cost']:null;$margin=$profit!==null&&$selling>0?$profit/$selling*100:null; ?><div class="d-flex justify-content-between mb-4"><h1 class="h3"><?= esc($product['name']) ?></h1><div><a class="btn btn-primary" href="<?= url_to('admin.products.edit',$product['id']) ?>">Edit</a> <?php if($product['status']==='active'): ?><a class="btn btn-outline-success" target="_blank" href="<?= url_to('catalog.product',$product['slug']) ?>">Public Preview</a><?php endif ?></div></div><div class="row g-4"><div class="col-lg-4"><div class="card border-0 p-3"><?php if($product['main_image']): ?><img class="img-fluid rounded" src="<?= base_url($product['main_image']) ?>" alt="<?= esc($product['name']) ?>"><?php endif ?><h2 class="h5 mt-3">Pricing & Margin</h2><p class="mb-1">Selling: ৳<?= number_format($selling,2) ?></p><p class="mb-1">Cost: <?= $product['purchase_cost']!==null?'৳'.number_format($product['purchase_cost'],2):'N/A' ?></p><p>Profit: <?= $profit!==null?'৳'.number_format($profit,2).' ('.number_format($margin,1).'%)':'N/A' ?></p></div></div><div class="col-lg-8"><div class="card border-0 p-4 mb-4"><dl class="row mb-0"><dt class="col-4">Product Code</dt><dd class="col-8"><?= esc($product['product_code']) ?></dd><dt class="col-4">Category</dt><dd class="col-8"><?= esc($product['category_name']??'—') ?></dd><dt class="col-4">Type</dt><dd class="col-8"><?= esc($product['stock_type']) ?></dd><dt class="col-4">Status</dt><dd class="col-8"><?= esc($product['status']) ?></dd><dt class="col-4">Stock</dt><dd class="col-8"><?= $product['stock_type']==='variant'?'Stored by variant':$product['stock_quantity'] ?></dd><dt class="col-4">SEO Title</dt><dd class="col-8"><?= esc($product['seo_title']?:'—') ?></dd><dt class="col-4">Created / Updated</dt><dd class="col-8"><?= esc($product['created_at']) ?> / <?= esc($product['updated_at']) ?></dd></dl></div><div class="card border-0 p-4"><h2 class="h5">Variants</h2><div class="table-responsive"><table class="table"><thead><tr><th>Name</th><th>SKU</th><th>Price</th><th>Cost</th><th>Stock</th></tr></thead><tbody><?php foreach($variants as $v): ?><tr><td><?= esc($v['variant_name']) ?></td><td><?= esc($v['sku']?:'—') ?></td><td>৳<?= number_format((float)($v['sale_price']?:$v['regular_price']),2) ?></td><td><?= $v['purchase_cost']!==null?'৳'.number_format($v['purchase_cost'],2):'N/A' ?></td><td><?= $v['stock_quantity'] ?></td></tr><?php endforeach ?></tbody></table></div><form method="post" action="<?= site_url('admin/products/'.$product['id'].'/duplicate') ?>"><?= csrf_field() ?><button class="btn btn-outline-secondary">Duplicate Product</button></form></div></div></div><?= $this->endSection() ?>
